import assert from 'node:assert/strict';
import axios from 'axios';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
assert.ok(process.env.COHERE_API_KEY, 'the application receives its organization API key');
assert.ok(process.env.COHERE_API_URL, 'the configured URL includes the rerank endpoint');
const documents = ['Mountain observatory evening sessions', 'Fresh bread and coffee', 'Observatory visitor guide'];
const { status, data } = await axios.post(process.env.COHERE_API_URL, {
  model: 'rerank-v3.5', query: 'observatory evening', top_n: 2, documents,
}, {
  headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${process.env.COHERE_API_KEY}` },
  timeout: 7500,
});
assert.equal(status, 200);
assert.ok(typeof data.id === 'string' && data.id.length > 0);
assert.equal(data.meta.api_version.version, '2');
assert.equal(data.meta.billed_units.search_units, 1);
assert.ok(data.meta.warnings.some((warning) => warning.includes('twin: relevance is lexical overlap') && warning.includes('no rerank model runs')), 'the response labels its lexical-overlap stand-in');
assert.equal(data.results.length, 2);
assert.deepEqual(data.results.map((result) => result.index), [0, 2]);
for (const result of data.results) {
  assert.ok(Number.isFinite(result.relevance_score) && result.relevance_score >= 0 && result.relevance_score <= 1);
  assert.equal(typeof documents[result.index], 'string');
}
assert.ok(data.results[0].relevance_score > data.results[1].relevance_score);
console.log(JSON.stringify({ highlights: data.results.map((result) => ({ text: documents[result.index], score: result.relevance_score })), billedUnits: data.meta.billed_units, warnings: data.meta.warnings }));
